import itertools
# dataset: 3 tasks
tasks = [
  dict(id="1", pri="P0", tags="tag1234567", due="", proj="proj123456789", summ="s12345678901234567890"),
  dict(id="2", pri="P1", tags="t2", due="", proj="p2", summ="s2"),
  dict(id="3", pri="P3", tags="", due="", proj="p333", summ="s33333"),
]
header = dict(id="ID", pri="Priority", tags="Tags", due="Due", proj="Project", summ="Summary")
keys = ["id","pri","tags","due","proj","summ"]
natural = dict(id=2, pri=8, tags=10, due=3, proj=13, summ=20)

def trunc(s, w, rule):
    if rule==1:
        return s[:w-1] if len(s)>w else s
    if rule==2:
        return s[:w-1] if len(s)>=w else s
    if rule==3:
        return s[:w] if len(s)>w else s
    if rule==4:  # len>w-1 -> s[:w-1]
        return s[:w-1] if len(s)>w-1 else s

def render(ws, rule):
    out=[]
    for t in [header]+tasks:
        cells=[]
        for k,w in zip(keys,ws):
            c=trunc(t[k],w,rule)
            cells.append(c.ljust(w))
        out.append("  ".join(cells))
    return out

def compositions(total, n, maxw):
    if n==1:
        if 0<=total<=maxw: yield (total,)
        return
    for i in range(0,min(total,maxw)+1):
        for rest in compositions(total-i, n-1, maxw):
            yield (i,)+rest

for rule in [1,2,3,4]:
    ok_all=True
    fits={}
    for w in range(8,68,2):
        try: lines=open(str(w)+'.txt').read().splitlines()[:4]
        except: continue
        found=None
        budget=w-10
        if budget<0: continue
        for ws in compositions(budget,6,30):
            if render(ws,rule)==lines:
                found=ws; break
        if found is None:
            ok_all=False
            break
        fits[w]=found
    if ok_all:
        print("RULE",rule,"fits all!")
        for w,ws in sorted(fits.items()): print(w,ws)
        break
    else:
        print("rule",rule,"failed at width",w)
EOF

